import{z as o,x as s,o as e,c as p,q as i,j as t,D as a,d as A,s as r,S as n,b as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"复现案例：训练配方","description":"","frontmatter":{"title":"复现案例：训练配方","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rw-case-training-recipe.md","filePath":"llm/rw-case-training-recipe.md","lastUpdated":1791413859000}'),D={name:"llm/rw-case-training-recipe.md"};function d(c,E,m,C,h,F){const B=s("Mermaid");return e(),p("div",null,[E[2]||(E[2]=i('<h1 id="复现案例-训练配方" tabindex="-1">复现案例：训练配方 <a class="header-anchor" href="#复现案例-训练配方" aria-label="Permalink to &quot;复现案例：训练配方&quot;">​</a></h1><div class="epigraph"><p>配方可信的标志，是它的每个数字都能指回一次可重算的实验；做不到这条的配方，只是很好的故事。</p><footer>—— 据 Groeneveld 等, OLMo: Accelerating the Science of Language Models, 2024 整理</footer></div><p><a href="/llm/rw-case-inference">上一课</a>的案例在推理侧，锚点是便宜的单步调度；本课走到另一端：训练配方的复现，以 OLMo 一系的开放全流程配方为锚。单步便宜、全量极贵、失败在几周后才暴露——预算结构与失败节奏与推理案例相反。预训练配方的判读底稿在<a href="/llm/pf2-opensource-recipes">开源配方对照</a>：规模分割、配比管线、超参迁移、日程退火、稳定件、评估声明六行；本课把这六行变成一条执行路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>配方复现的难点在「组合」：配方声称的不是单个部件的效果，而是配比、日程、稳定件三者的组合效应。逐件消融覆盖不了组合——数据配比的贡献依赖退火日程，退火的贡献依赖数据配比；单独对齐任何一件都可能「对上」，组合起来仍对不上。另一个难点是开销曲线：全量一次的成本让穷举不可能，所以配方复现注定是阶梯上的抽样艺术——在哪一级阶梯上问哪一个问题，问错了问题，预算就变成了学费。</p><p><span class="marginnote">「训练配方」可以类比蛋糕配方：数据配比是面粉和糖的比例，日程是烤箱温度随时间怎么调，稳定件是泡打粉这类保险。复现难在三者互相影响——换了糖的比例，烤多久也得跟着变，所以逐件单独对齐可能都对，合起来仍不对。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按第一课声明：目标线选结论线——在缩小的规模上复现配比与日程的排序；数字线只对 pilot 级及以下承诺。执行四步。第一步，判读出决策表：六行逐项填，披露档位标注；开放配方（OLMo 口径）多数行显式，封闭报告按缺失档降级预期。第二步，超参迁移重调：论文的学习率与权重衰减在其规模调出，先在你的目标规模上为「他们的方法」与「基线方法」各重调一轮优化超参，再谈配比——这步服务两个目的：外推修正与基线资格（<a href="/llm/rw-baseline-alignment">数值对齐与基线校准</a>）。第三步，阶梯执行：tiny 通管线、small 看趋势、pilot 定关键判断；配比消融在 pilot 级做同预算对照（<a href="/llm/rw-ablation-design">消融设计的工程学</a>），日程与退火单独消融。第四步，对齐账收口：同数据快照上重算 loss 曲线形态，与配方公开的中间 checkpoint 对表。</p><p><span class="marginnote">数字实例：假设目标规模是 7B 模型配一万亿 token，阶梯大概是 70M 配 10B 的 tiny、700M 配 100B 的 small、1.5B 配 200B 的 pilot——每上一级算力都上一个台阶（tiny 到 small 约涨百倍，small 到 pilot 也有四五倍），要回答的问题也从「管线通不通」升级到「排序在不在」，钱只花在能改判断的那一级。</span></p>',9)),(e(),t(n,null,{default:a(()=>[r(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RECIPE%5B%22%E9%85%8D%E6%96%B9%E8%AE%BA%E6%96%87%22%5D%20--%3E%20TABLE%5B%22%E5%86%B3%E7%AD%96%E8%A1%A8%E5%85%AD%E8%A1%8C%2B%E6%8A%AB%E9%9C%B2%E6%A1%A3%E4%BD%8D%22%5D%0A%20%20TABLE%20--%3E%20HP%5B%22%E8%B6%85%E5%8F%82%E8%BF%81%E7%A7%BB%E9%87%8D%E8%B0%83%EF%BC%9A%E6%96%B9%E6%B3%95%E4%B8%8E%E5%9F%BA%E7%BA%BF%E5%90%84%E4%B8%80%E8%BD%AE%22%5D%0A%20%20HP%20--%3E%20LADDER%5B%22%E9%98%B6%E6%A2%AF%EF%BC%9Atiny%E2%86%92small%E2%86%92pilot%22%5D%0A%20%20LADDER%20--%3E%20AB1%5B%22%E9%85%8D%E6%AF%94%E6%B6%88%E8%9E%8D%EF%BC%9A%E5%90%8C%E9%A2%84%E7%AE%97%22%5D%0A%20%20LADDER%20--%3E%20AB2%5B%22%E6%97%A5%E7%A8%8B%E6%B6%88%E8%9E%8D%EF%BC%9A%E5%90%8C%E9%85%8D%E6%AF%94%22%5D%0A%20%20AB1%20--%3E%20VERDICT%5B%22%E7%BB%93%E8%AE%BA%E7%BA%BF%E5%88%A4%E5%AE%9A%EF%BC%9A%E6%8E%92%E5%BA%8F%E5%A4%8D%E5%87%BA%EF%BC%9F%22%5D%0A%20%20AB2%20--%3E%20VERDICT%0A%20%20VERDICT%20--%3E%20LEDGER%5B%22%E5%AF%B9%E9%BD%90%E8%B4%A6%EF%BC%9A%E4%B8%AD%E9%97%B4%20checkpoint%20%E5%AF%B9%E8%A1%A8%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l("h2",{id:"机制",tabindex:"-1"},[A("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=l("p",null,"为什么「超参迁移」行是枢纽：配比的比较只有在优化超参各自调平后才有语义；直接照搬论文超参到缩小规模，优化器欠账会冒充配比效应——两个配比谁对谁错，判给了一个没人测过的学习率。这就是配方复现里最常见的假阴性：论文的配比没错，你的迁移错了。为什么日程要单独消融：学习率退火的尾部贡献最终 loss 的一大块，配比效应必须在同一日程下比较；反过来，日程的效应也要在同一配比下比较。组合层的验证靠正交小网格：在 pilot 级取配比两档乘日程两档的最小网格，四格读出交互项的方向——不追全网格，只判「组合是否可分」。开放配方的独特优势在账本公开：中间 checkpoint 的评测分数可查（Groeneveld 等 2024 的口径），你的评测管线先对它的公开 checkpoint 校准，归因空间直接砍半——评测侧的差异与训练侧的差异提前分开。",-1)),(e(),t(n,null,{default:a(()=>[r(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22pilot%20%E7%BA%A7%E6%9C%80%E5%B0%8F%E7%BD%91%E6%A0%BC%EF%BC%9A%E9%85%8D%E6%AF%94%E4%B8%A4%E6%A1%A3%20%C3%97%20%E6%97%A5%E7%A8%8B%E4%B8%A4%E6%A1%A3%22%5D%20--%3E%20C11%5B%22%E9%85%8D%E6%AF%94%20A%E3%80%81%E6%97%A5%E7%A8%8B%E4%B8%80%22%5D%0A%20%20G%20--%3E%20C21%5B%22%E9%85%8D%E6%AF%94%20B%E3%80%81%E6%97%A5%E7%A8%8B%E4%B8%80%22%5D%0A%20%20G%20--%3E%20C12%5B%22%E9%85%8D%E6%AF%94%20A%E3%80%81%E6%97%A5%E7%A8%8B%E4%BA%8C%22%5D%0A%20%20G%20--%3E%20C22%5B%22%E9%85%8D%E6%AF%94%20B%E3%80%81%E6%97%A5%E7%A8%8B%E4%BA%8C%22%5D%0A%20%20C11%20--%3E%20R%5B%22%E5%9B%9B%E6%A0%BC%E8%AF%BB%E6%95%B0%22%5D%0A%20%20C21%20--%3E%20R%0A%20%20C12%20--%3E%20R%0A%20%20C22%20--%3E%20R%0A%20%20R%20--%3E%20D1%5B%22%E5%90%8C%E4%B8%80%E6%97%A5%E7%A8%8B%E4%B8%8B%E9%85%8D%E6%AF%94%E6%8E%92%E5%BA%8F%E4%B8%8D%E5%8F%98%20%E2%86%92%20%E7%BB%84%E5%90%88%E5%8F%AF%E5%88%86%22%5D%0A%20%20R%20--%3E%20D2%5B%22%E5%8D%95%E7%8B%AC%E9%83%BD%E5%A5%BD%E3%80%81%E5%90%88%E8%B5%B7%E6%9D%A5%E5%8F%98%E5%B7%AE%20%E2%86%92%20%E8%B4%9F%E4%BA%A4%E4%BA%92%EF%BC%8C%E9%9C%80%E8%AE%B0%E5%BD%95%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=i('<p><span class="marginnote">常见误区：照搬论文的学习率到缩小规模，看到配比 B 输了就断言「论文配比复现不了」。实际很可能是优化器欠账——B 在这个学习率下根本没被调平。正文说的「假阴性」就是这个：论文没错，你的迁移错了。</span></p><p><span class="marginnote">对表公开 checkpoint 是配方复现独有的免费锚点：不用训练任何东西，先让你的评测栈在他们的中间模型上复出公开分数。对不上时，问题在评测管线而不是训练——归因六步直接跳过整个训练侧。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>案例边界有三。数据的地域与时效漂移使「同一份配比」不可得时，声明近似档位，结论线自动降级。分词器不同则全部数字换坐标系，连结论线都要重估——粒度变化会改变配比的相对含义。最后，组合的边界诚实：pilot 级的四格网格只验证「可分性」的方向，不验证全量规模下的组合值；配方复现的结论通常停在「排序与方向」，把它写成「复现了配方」就是越档引用。产物按报告骨架落档，配比消融的每个格子挂 run，死路（比如某配比在 small 级已发散）入档案。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>配方复现的目标线默认结论线；数字线只对 pilot 及以下承诺。</li><li>六行决策表先行；超参迁移重调是枢纽——优化器欠账会冒充配比效应。</li><li>配比与日程互相消融：配比在同日程下比，日程在同配比下比；交互用最小四格网格判方向。</li><li>对表公开 checkpoint 是免费锚点：先校准评测栈，再谈训练侧归因。</li><li>出处：Groeneveld 等, 2024；判读口径见<a href="/llm/pf2-opensource-recipes">开源配方对照</a>；管理口径见<a href="/llm/ti-recipe-management">训练配方管理</a>。</li></ul>',6))])}const _=o(D,[["render",d]]);export{u as __pageData,_ as default};
